package matrix

import (
	"errors"
	"strconv"
	"strings"
)

type matrix struct {
	rows [][]int
}

// Matrix is a pointer to the underlying matrix data so that it can be
// compared against nil.
type Matrix = *matrix

// New parses a string of newline-separated rows of space-separated integers.
// It returns an error if any row is empty, any token is not an integer, or
// the rows have uneven lengths.
func New(s string) (Matrix, error) {
	m := &matrix{}
	for _, line := range strings.Split(s, "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("matrix row is empty")
		}
		row := make([]int, len(fields))
		for i, f := range fields {
			n, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[i] = n
		}
		if len(m.rows) > 0 && len(row) != len(m.rows[0]) {
			return nil, errors.New("matrix rows have uneven lengths")
		}
		m.rows = append(m.rows, row)
	}
	return m, nil
}

// Cols returns the columns of the matrix, each as an independent copy.
func (m Matrix) Cols() [][]int {
	if len(m.rows) == 0 {
		return nil
	}
	cols := make([][]int, len(m.rows[0]))
	for c := range cols {
		cols[c] = make([]int, len(m.rows))
		for r, row := range m.rows {
			cols[c][r] = row[c]
		}
	}
	return cols
}

// Rows returns the rows of the matrix, each as an independent copy.
func (m Matrix) Rows() [][]int {
	rows := make([][]int, len(m.rows))
	for i, r := range m.rows {
		rows[i] = make([]int, len(r))
		copy(rows[i], r)
	}
	return rows
}

// Set sets the element at (row, col) to val. It returns false if the
// coordinates are out of range, leaving the matrix unchanged.
func (m Matrix) Set(row, col, val int) bool {
	if row < 0 || row >= len(m.rows) || col < 0 || col >= len(m.rows[0]) {
		return false
	}
	m.rows[row][col] = val
	return true
}
